/** Thrown when a repair line item is not found. */
export class RepairLineItemNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Repair line item not found: ${id}`)
    this.name = 'RepairLineItemNotFoundError'
  }
}

/** Thrown when a repair has been completed and cannot be modified. */
export class RepairCompletedError extends Error {
  constructor(public readonly id: string) {
    super(`Cannot modify completed repair: ${id}`)
    this.name = 'RepairCompletedError'
  }
}

/** Thrown when a labor service is not found. */
export class LaborServiceNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Labor service not found: ${id}`)
    this.name = 'LaborServiceNotFoundError'
  }
}

