import crypto from 'crypto'
import { db, sqliteDb } from '@/db/index.js'
import type Database from 'better-sqlite3'
import {
  customers,
  bicycles,
  repairs,
  repairLineItems,
  workLogs,
  vatRates,
  type Customer as DbCustomer,
  type Bicycle as DbBicycle,
} from '@/db/schema.js'
import { eq, asc } from 'drizzle-orm'

// Import shared types and validations
import {
  createIntakeBicycleSchema,
  repairIntakeSchema,
  transitionRepairStatusSchema,
  updateRepairSchema,
  createRepairLineItemSchema,
  updateRepairLineItemSchema,
  assignWorkerSchema,
} from '@shared/validations/repair.js'

// Import types for local use and re-export
import type {
  RepairStatus,
  HoldReason,
  TransitionRepairStatusInput,
  UpdateRepairInput,
  CreateRepairLineItemInput,
  UpdateRepairLineItemInput,
  AssignWorkerInput,
} from '@shared/validations/repair.js'

// Re-export types for use in routes and frontend
export type {
  RepairStatus,
  HoldReason,
  TransitionRepairStatusInput,
  UpdateRepairInput,
  CreateRepairLineItemInput,
  UpdateRepairLineItemInput,
  AssignWorkerInput,
} from '@shared/validations/repair.js'

// Import shared types for type annotations
import type {
  RepairIntakeInput,
  LaborService,
} from '@shared/types/repair.js'
// ============================================================================
// Raw SQL executor — avoids Drizzle Date/number conversion issues with timestamps
// ============================================================================

function run(sqlStr: string, params?: unknown[]): void {
  const client = sqliteDb as Database.Database
  client.prepare(sqlStr).run(...(params ?? []))
}

// ============================================================================
// DTO shapes returned by the API
// ============================================================================

/** Compact customer shape for intake selectors */
export interface IntakeCustomer {
  id: string
  type: 'private' | 'company'
  firstName: string | null
  lastName: string | null
  companyName: string | null
  phone: string | null
  email: string | null
}

/** Compact bicycle shape for intake selectors */
export interface IntakeBicycle {
  id: string
  brand: string
  model: string
  color: string | null
  year: number | null
}

/** Customer with their bicycles — returned during intake lookup */
export interface CustomerWithBicycles extends IntakeCustomer {
  bicycles: IntakeBicycle[]
}

/** Repair detail shape returned by API endpoints */
export interface RepairDetail {
  id: string
  bicycleId: string
  assignedTo: string | null
  status: RepairStatus
  customerNotes: string | null
  internalNotes: string | null
  holdReason: HoldReason | null
  holdReasonNote: string | null
  plannedDate: number | null
  pickupDate: number | null
  completedAt: number | null
  createdAt: number
}

/** Filter options for the repair list query */
export interface RepairListFilters {
  status?: RepairStatus
  assignedTo?: string | null
  pickupDateFilter?: 'today' | 'this_week'
  /** Inclusive epoch-ms lower bound for date-range filtering (plannedDate, fallback createdAt) */
  from?: number
  /** Inclusive epoch-ms upper bound for date-range filtering (plannedDate, fallback createdAt) */
  to?: number
  /** Comma-separated list of statuses to include (e.g. "in_progress,on_hold") */
  statusIn?: string[]
  /** Filter repairs by bicycle IDs — used for customer detail panel */
  bicycleIds?: string[]
}

/** Paginated response shape for the repair list */
export interface PaginatedRepairs {
  repairs: RepairDetailWithCustomer[]
  total: number
  page: number
  pageSize: number
  totalPages: number
}

/** Repair detail enriched with customer name and bicycle info for list display */
export interface RepairDetailWithCustomer extends Omit<RepairDetail, 'bicycleId'> {
  customerName: string | null
  bicycleBrand: string
  bicycleModel: string
  bicycleColor: string | null
}

// ============================================================================
// Error types
// ============================================================================

/** Thrown when a repair lookup by ID finds no matching record. */
export class RepairNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Repair not found: ${id}`)
    this.name = 'RepairNotFoundError'
  }
}

/** Thrown when a status transition is invalid. */
export class InvalidStatusTransitionError extends Error {
  constructor(
    public readonly from: RepairStatus,
    public readonly to: RepairStatus,
  ) {
    super(`Invalid status transition: ${from} → ${to}`)
    this.name = 'InvalidStatusTransitionError'
  }
}

/** Thrown when a hold reason is set without the required note. */
export class MissingHoldReasonNoteError extends Error {
  constructor() {
    super('holdReasonNote is required when holdReason is set')
    this.name = 'MissingHoldReasonNoteError'
  }
}

// ============================================================================
// Valid status transitions (from CONTEXT.md decision #13)
// ============================================================================

const VALID_TRANSITIONS: Record<RepairStatus, RepairStatus[]> = {
  intake: ['in_progress'],
  in_progress: ['on_hold', 'verified'],
  on_hold: ['in_progress'],
  verified: ['ready'],
  ready: ['completed'],
  completed: [], // terminal — no transitions allowed (except via cancel)
  cancelled: [], // terminal
}

/** All statuses that can be cancelled from */
const CANCEL_TARGETS: RepairStatus[] = [
  'intake', 'in_progress', 'on_hold', 'verified', 'ready'
]

// ============================================================================
// Repository layer — database access functions
// ============================================================================

/** Find a single repair by ID. */
async function repoFindRepairById(id: string): Promise<typeof repairs.$inferSelect | undefined> {
  const [result] = await db
    .select()
    .from(repairs)
    .where(eq(repairs.id, id))

  return result ?? undefined
}

/** Create a new repair record using raw SQL (timestamp columns need epoch ms). */
async function repoCreateRepair(data: {
  id: string
  bicycleId: string
  assignedTo: string | null
  status: string
  customerNotes: string | null
  internalNotes: string | null
  holdReason: string | null
  holdReasonNote: string | null
  plannedDate: number | null
  pickupDate: number | null
  completedAt: number | null
}): Promise<typeof repairs.$inferSelect> {
  const now = Date.now()
  run(
    'INSERT INTO repairs (id, bicycle_id, assigned_to, status, customer_notes, internal_notes, hold_reason, hold_reason_note, planned_date, pickup_date, completed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [data.id, data.bicycleId, data.assignedTo, data.status, data.customerNotes, data.internalNotes, data.holdReason, data.holdReasonNote, data.plannedDate, data.pickupDate, data.completedAt, now]
  )

  const [created] = await db.select().from(repairs).where(eq(repairs.id, data.id))
  return created!
}

/** Update a repair record using raw SQL. */
async function repoUpdateRepair(id: string, updates: {
  status?: string
  customerNotes?: string | null
  internalNotes?: string | null
  holdReason?: string | null
  holdReasonNote?: string | null
  plannedDate?: number | null
  pickupDate?: number | null
}): Promise<typeof repairs.$inferSelect> {
  const setClauses: string[] = []
  const params: unknown[] = []

  if (updates.status !== undefined) {
    setClauses.push('status = ?')
    params.push(updates.status)
  }
  if (updates.customerNotes !== undefined) {
    setClauses.push('customer_notes = ?')
    params.push(updates.customerNotes ?? null)
  }
  if (updates.internalNotes !== undefined) {
    setClauses.push('internal_notes = ?')
    params.push(updates.internalNotes ?? null)
  }
  if (updates.holdReason !== undefined) {
    setClauses.push('hold_reason = ?')
    params.push(updates.holdReason ?? null)
  }
  if (updates.holdReasonNote !== undefined) {
    setClauses.push('hold_reason_note = ?')
    params.push(updates.holdReasonNote ?? null)
  }
  if (updates.plannedDate !== undefined) {
    setClauses.push('planned_date = ?')
    params.push(updates.plannedDate ?? null)
  }
  if (updates.pickupDate !== undefined) {
    setClauses.push('pickup_date = ?')
    params.push(updates.pickupDate ?? null)
  }

  const sqlStr = `UPDATE repairs SET ${setClauses.join(', ')} WHERE id = ?`
  run(sqlStr, [...params, id])

  const [updated] = await db.select().from(repairs).where(eq(repairs.id, id))
  if (!updated) throw new RepairNotFoundError(id)
  return updated
}

/** Record a status transition in the audit trail using raw SQL. */
async function repoRecordStatusTransition(repairId: string, status: RepairStatus): Promise<void> {
  const now = Date.now()
  run(
    'INSERT INTO repair_status_history (id, repair_id, status, transitioned_at) VALUES (?, ?, ?, ?)',
    [crypto.randomUUID(), repairId, status, now]
  )
}

/** Find a single customer by ID. */
async function repoFindCustomerById(id: string): Promise<DbCustomer | undefined> {
  const [result] = await db
    .select()
    .from(customers)
    .where(eq(customers.id, id))

  return result ?? undefined
}

/** Create a new customer record using raw SQL. */
async function repoCreateNewCustomer(data: {
  firstName?: string
  lastName?: string
  companyName?: string
  phone: string
  email: string
}): Promise<string> {
  const id = crypto.randomUUID()
  run(
    'INSERT INTO customers (id, type, first_name, last_name, company_name, vat_id, phone, email, street, number, bus, postal_code, city, country, notification_preference) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [id, data.companyName ? 'company' : 'private', data.firstName ?? null, data.lastName ?? null, data.companyName ?? null, null, data.phone ?? null, data.email ?? null, null, null, null, null, null, 'BE', null]
  )

  return id
}

/** Find all bicycles for a given customer. */
async function repoFindBicyclesByCustomerId(customerId: string): Promise<DbBicycle[]> {
  return db
    .select()
    .from(bicycles)
    .where(eq(bicycles.customerId, customerId))
    .orderBy(asc(bicycles.createdAt))
}

/** Create a new bicycle record using raw SQL (timestamp column). */
async function repoCreateNewBicycle(data: {
  brand: string
  model: string
  color: string
}, customerId: string | null): Promise<string> {
  const id = crypto.randomUUID()
  const now = Date.now()
  // Walk-in repairs create bicycles as inventory; customer-linked repairs use 'customer_owned'
  const source = customerId ? 'customer_owned' : 'inventory'
  run(
    'INSERT INTO bicycles (id, source, template_id, customer_id, brand, model, year, color, frame_size, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [id, source, null, customerId ?? null, data.brand, data.model, null, data.color ?? null, null, 'inventory', now]
  )

  return id
}

// ============================================================================
// Helpers — map between DB records and DTO shapes
// ============================================================================

/** Map a DB repair to the RepairDetail shape. */
function toRepairDetail(repair: typeof repairs.$inferSelect): RepairDetail {
  return {
    id: repair.id,
    bicycleId: repair.bicycleId,
    assignedTo: repair.assignedTo,
    status: repair.status as RepairStatus,
    customerNotes: repair.customerNotes,
    internalNotes: repair.internalNotes,
    holdReason: repair.holdReason as HoldReason | null,
    holdReasonNote: repair.holdReasonNote,
    plannedDate: repair.plannedDate ?? null,
    pickupDate: repair.pickupDate ?? null,
    completedAt: repair.completedAt ?? null,
    createdAt: repair.createdAt,
  }
}

/** Map a DB customer to the IntakeCustomer shape. */
function toIntakeCustomer(customer: DbCustomer): IntakeCustomer {
  return {
    id: customer.id,
    type: customer.type,
    firstName: customer.firstName,
    lastName: customer.lastName,
    companyName: customer.companyName,
    phone: customer.phone,
    email: customer.email,
  }
}

/** Map a DB bicycle to the IntakeBicycle shape. */
function toIntakeBicycle(bicycle: DbBicycle): IntakeBicycle {
  return {
    id: bicycle.id,
    brand: bicycle.brand,
    model: bicycle.model,
    color: bicycle.color,
    year: bicycle.year,
  }
}

// ============================================================================
// Public API — Read operations
// ============================================================================

/**
 * Get all bicycles for a customer — used during intake to show selection options.
 *
 * @param customerId - Customer identifier
 * @returns Array of bicycles belonging to the customer
 */
export async function getCustomerBicycles(customerId: string): Promise<IntakeBicycle[]> {
  const bicycleList = await repoFindBicyclesByCustomerId(customerId)
  return bicycleList.map(toIntakeBicycle)
}

/**
 * Get a customer with their bicycles — used during intake lookup.
 *
 * @param customerId - Customer identifier
 * @returns Customer detail with associated bicycles, or undefined if not found
 */
export async function getCustomerWithBicycles(customerId: string): Promise<CustomerWithBicycles | undefined> {
  const customer = await repoFindCustomerById(customerId)
  if (!customer) return undefined

  const bicycleList = await repoFindBicyclesByCustomerId(customerId)

  return {
    ...toIntakeCustomer(customer),
    bicycles: bicycleList.map(toIntakeBicycle),
  }
}

/**
 * Get a paginated list of repairs with filtering and sorting.
 *
 * Enriches each repair with customer name, bicycle brand/model/color for display.
 * Supports filtering by status, assigned worker, and pickup date range.
 *
 * @param filters - Optional filter criteria
 * @param page - Page number (1-indexed)
 * @param pageSize - Number of items per page
 * @returns Paginated repair list with metadata
 */
export async function getRepairsList(
  filters: RepairListFilters = {},
  page: number = 1,
  pageSize: number = 20,
): Promise<PaginatedRepairs> {
  const offset = (page - 1) * pageSize
  const client = sqliteDb as Database.Database

  // Build WHERE clause and params for raw SQL
  const whereParts: string[] = []
  const params: unknown[] = []

  if (filters.status) {
    whereParts.push('r.status = ?')
    params.push(filters.status)
  }

  if (filters.assignedTo !== undefined && filters.assignedTo !== null) {
    whereParts.push('r.assigned_to = ?')
    params.push(filters.assignedTo)
  } else if (filters.assignedTo === null) {
    // Explicitly filter for unassigned repairs
    whereParts.push('r.assigned_to IS NULL')
  }

  // Pickup date filtering
  const now = Date.now()
  if (filters.pickupDateFilter === 'today') {
    const todayStart = new Date(now).setHours(0, 0, 0, 0)
    const todayEnd = new Date(now).setHours(23, 59, 59, 999)
    whereParts.push('r.pickup_date >= ? AND r.pickup_date <= ?')
    params.push(todayStart, todayEnd)
  } else if (filters.pickupDateFilter === 'this_week') {
    const today = new Date(now)
    const dayOfWeek = today.getDay()
    // Monday is 0 for our purposes (ISO week start)
    const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek
    const weekStart = new Date(today)
    weekStart.setDate(today.getDate() + mondayOffset)
    weekStart.setHours(0, 0, 0, 0)
    const weekEnd = new Date(weekStart)
    weekEnd.setDate(weekStart.getDate() + 6)
    weekEnd.setHours(23, 59, 59, 999)
    whereParts.push('r.pickup_date >= ? AND r.pickup_date <= ?')
    params.push(weekStart.getTime(), weekEnd.getTime())
  }

  // Date-range filtering: uses plannedDate with fallback to createdAt (COALESCE)
  if (filters.from !== undefined) {
    whereParts.push('COALESCE(r.planned_date, r.created_at) >= ?')
    params.push(filters.from)
  }
  if (filters.to !== undefined) {
    whereParts.push('COALESCE(r.planned_date, r.created_at) <= ?')
    params.push(filters.to)
  }

  // Status-in filtering: comma-separated list of statuses to include
  if (filters.statusIn && filters.statusIn.length > 0) {
    const placeholders = filters.statusIn.map(() => '?').join(',')
    whereParts.push(`r.status IN (${placeholders})`)
    params.push(...filters.statusIn)
  }

  // Bicycle IDs filtering — used for customer detail panel (repairs across all customer bikes)
  if (filters.bicycleIds && filters.bicycleIds.length > 0) {
    const placeholders = filters.bicycleIds.map(() => '?').join(',')
    whereParts.push(`r.bicycle_id IN (${placeholders})`)
    params.push(...filters.bicycleIds)
  }

  const whereClause = whereParts.length > 0 ? `WHERE ${whereParts.join(' AND ')}` : ''

  // Get total count for pagination (use alias r to match whereParts)
  const [countRow] = client.prepare(`SELECT COUNT(*) AS cnt FROM repairs r ${whereClause}`).all(...params) as Array<{ cnt: number }>
  const total = Number(countRow.cnt)
  const totalPages = Math.ceil(total / pageSize) || 1

  // Fetch enriched repair list with customer name and bicycle info
  const rows = client.prepare(`
    SELECT
      r.id,
      r.bicycle_id,
      r.assigned_to,
      r.status,
      r.customer_notes,
      r.internal_notes,
      r.hold_reason,
      r.hold_reason_note,
      r.planned_date,
      r.pickup_date,
      r.completed_at,
      r.created_at,
      c.first_name || ' ' || c.last_name AS customer_name,
      b.brand AS bicycle_brand,
      b.model AS bicycle_model,
      b.color AS bicycle_color
    FROM repairs r
    INNER JOIN bicycles b ON r.bicycle_id = b.id
    LEFT JOIN customers c ON b.customer_id = c.id
    ${whereClause}
    ORDER BY r.planned_date DESC NULLS LAST, r.created_at DESC
    LIMIT ? OFFSET ?
  `).all(...params, pageSize, offset) as Array<{
    id: string
    bicycle_id: string
    assigned_to: string | null
    status: string
    customer_notes: string | null
    internal_notes: string | null
    hold_reason: string | null
    hold_reason_note: string | null
    planned_date: number | null
    pickup_date: number | null
    completed_at: number | null
    created_at: number
    customer_name: string | null
    bicycle_brand: string
    bicycle_model: string
    bicycle_color: string | null
  }>

  const repairList: RepairDetailWithCustomer[] = rows.map((row) => ({
    id: row.id,
    bicycleId: row.bicycle_id,
    assignedTo: row.assigned_to,
    status: row.status as RepairStatus,
    customerNotes: row.customer_notes,
    internalNotes: row.internal_notes,
    holdReason: row.hold_reason as HoldReason | null,
    holdReasonNote: row.hold_reason_note,
    plannedDate: row.planned_date,
    pickupDate: row.pickup_date,
    completedAt: row.completed_at,
    createdAt: row.created_at,
    customerName: row.customer_name || null,
    bicycleBrand: row.bicycle_brand,
    bicycleModel: row.bicycle_model,
    bicycleColor: row.bicycle_color,
  }))

  return {
    repairs: repairList,
    total,
    page,
    pageSize,
    totalPages,
  }
}

// ============================================================================
// Public API — Write operations (Intake Flow)
// ============================================================================

/**
 * Create a new repair via the intake flow.
 *
 * This is an atomic operation that:
 * 1. Validates the intake input schema
 * 2. Creates a new customer if customerMode='new'
 * 3. Creates a new bicycle if bicycleMode='create_new' (linked to the customer)
 * 4. Creates the repair record with status='intake' and assignedTo=NULL
 * 5. Records the initial status transition in the audit trail
 *
 * @param input - Validated intake input from the form
 * @returns The created RepairDetail
 */
export async function createRepairIntake(input: RepairIntakeInput): Promise<RepairDetail> {
  // Validate against the combined schema
  const validated = repairIntakeSchema.parse(input)

  let customerId: string | null = null

  // Step 1: Handle customer (existing, inline creation, or walk-in/none)
  if (validated.customerMode === 'new') {
    const newCustomerData = validated.newCustomer as Parameters<typeof repoCreateNewCustomer>[0]
    customerId = await repoCreateNewCustomer(newCustomerData)
  } else if (validated.customerMode === 'existing') {
    // existing mode — verify the customer exists
    const existingCustomer = await repoFindCustomerById(validated.existingCustomerId!)
    if (!existingCustomer) {
      throw new RepairNotFoundError(`Customer not found: ${validated.existingCustomerId}`)
    }
    customerId = validated.existingCustomerId!
  } else {
    // 'none' mode — walk-in, no customer
    customerId = null
  }

  // Step 2: Handle bicycle (select existing or inline creation)
  let bicycleId: string

  if (validated.bicycleMode === 'create_new') {
    const newBicycleData = createIntakeBicycleSchema.parse(validated.newBicycle!)
    bicycleId = await repoCreateNewBicycle(newBicycleData, customerId)
  } else {
    // select_existing mode — verify the bicycle exists and belongs to the customer
    if (!validated.existingBicycleId) {
      throw new Error('existingBicycleId is required when selecting an existing bicycle')
    }

    const [bicycle] = await db
      .select()
      .from(bicycles)
      .where(eq(bicycles.id, validated.existingBicycleId!))

    if (!bicycle) {
      throw new RepairNotFoundError(`Bicycle not found: ${validated.existingBicycleId}`)
    }

    // Verify the bicycle belongs to the selected customer (or is shop inventory / walk-in)
    if (customerId !== null && bicycle.customerId !== null && bicycle.customerId !== customerId) {
      throw new Error('Selected bicycle does not belong to the chosen customer')
    }

    bicycleId = validated.existingBicycleId!
  }

  // Step 3: Create the repair record
  const repairData = {
    id: crypto.randomUUID(),
    bicycleId,
    assignedTo: null, // deferred assignment — manager assigns later
    status: 'intake',
    customerNotes: validated.customerNotes || null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate: (validated as any).plannedDate ?? null,
    pickupDate: (validated as any).pickupDate ?? null,
    completedAt: null,
  }

  const created = await repoCreateRepair(repairData)

  // Step 4: Record initial status in audit trail
  await repoRecordStatusTransition(created.id, 'intake')

  return toRepairDetail(created)
}

/**
 * Transition a repair to a new status.
 *
 * Validates the transition against the allowed state machine, records the
 * hold reason/note if applicable, and updates the repair record atomically.
 *
 * @param id - Repair identifier
 * @param input - Target status with optional hold reason details
 * @returns The updated RepairDetail
 */
export async function transitionRepairStatus(
  id: string,
  input: TransitionRepairStatusInput,
): Promise<RepairDetail> {
  // Validate the transition input
  const validated = transitionRepairStatusSchema.parse(input)

  // Look up current repair state
  const current = await repoFindRepairById(id)
  if (!current) {
    throw new RepairNotFoundError(id)
  }

  const currentStatus = current.status as RepairStatus
  const targetStatus = validated.targetStatus as RepairStatus

  // Validate the transition is allowed
  validateTransition(currentStatus, targetStatus)

  // If transitioning to on_hold, require holdReason and holdReasonNote
  if (targetStatus === 'on_hold') {
    if (!validated.holdReason) {
      throw new MissingHoldReasonNoteError()
    }
    if (!validated.holdReasonNote) {
      throw new MissingHoldReasonNoteError()
    }
  }

  // Build update payload — only include hold fields when transitioning to on_hold
  const updates: Parameters<typeof repoUpdateRepair>[1] = { status: targetStatus }

  if (targetStatus === 'on_hold') {
    updates.holdReason = validated.holdReason as HoldReason | null
    updates.holdReasonNote = validated.holdReasonNote || null
  } else {
    // Clear hold fields when leaving on_hold state
    updates.holdReason = null
    updates.holdReasonNote = null
  }

  // Apply the update
  const updated = await repoUpdateRepair(id, updates)

  // Record in audit trail
  await repoRecordStatusTransition(updated.id, targetStatus)

  return toRepairDetail(updated)
}

/**
 * Update repair notes (customer-facing and/or internal).
 *
 * Both note types are always editable regardless of status.
 *
 * @param id - Repair identifier
 * @param input - Partial update with customerNotes and/or internalNotes
 * @returns The updated RepairDetail
 */
export async function updateRepairNotes(
  id: string,
  input: UpdateRepairInput,
): Promise<RepairDetail> {
  // Validate the update input
  const validated = updateRepairSchema.parse(input)

  // Look up current repair state
  const current = await repoFindRepairById(id)
  if (!current) {
    throw new RepairNotFoundError(id)
  }

  // Build partial update — only include fields that were provided
  const updates: Parameters<typeof repoUpdateRepair>[1] = {}

  if (validated.customerNotes !== undefined) {
    updates.customerNotes = validated.customerNotes || null
  }
  if (validated.internalNotes !== undefined) {
    updates.internalNotes = validated.internalNotes || null
  }
  if (validated.plannedDate !== undefined) {
    updates.plannedDate = validated.plannedDate ?? null
  }
  if (validated.pickupDate !== undefined) {
    updates.pickupDate = validated.pickupDate ?? null
  }

  // Apply the update
  const updated = await repoUpdateRepair(id, updates)

  return toRepairDetail(updated)
}

// ============================================================================
// Validation helpers
// ============================================================================

/** Validate that a status transition is allowed by the state machine. */
function validateTransition(from: RepairStatus, to: RepairStatus): void {
  // Cancel is always allowed from non-terminal states
  if (to === 'cancelled' && CANCEL_TARGETS.includes(from)) {
    return
  }

  const allowed = VALID_TRANSITIONS[from]
  if (!allowed || !allowed.includes(to)) {
    throw new InvalidStatusTransitionError(from, to)
  }
}

