/** Enriched repair detail returned by GET /repairs/:id */
export interface RepairDetailEnriched {
  /** The repair header with epoch ms timestamps */
  repair: {
    id: string
    bicycleId: string
    assignedTo: string | null
    status: RepairStatus
    customerNotes: string | null
    internalNotes: string | null
    holdReason: HoldReason | null
    holdReasonNote: string | null
    plannedDate: number | null
    pickupDate: number | null
    completedAt: number | null
    createdAt: number
  }
  /** Customer associated with the bicycle */
  customer?: {
    id: string
    firstName: string | null
    lastName: string | null
    companyName: string | null
    phone: string | null
    email: string | null
  }
  /** Bicycle being serviced */
  bicycle: {
    id: string
    brand: string
    model: string
    color: string | null
    year: number | null
  }
  /** Line items (parts and labor) for this repair */
  lineItems: typeof repairLineItems.$inferSelect[]
  /** Work log timer sessions for this repair (epoch ms timestamps) */
  workLogs: {
    id: string
    repairId: string
    userId: string
    startedAt: number | null
    endedAt: number | null
    durationMs?: number
  }[]
}

/**
 * Get a repair by ID with full enrichment: customer, bicycle, line items, work logs.
 *
 * @param id - Repair identifier
 * @returns Enriched repair detail or undefined if not found
 */
export async function getRepairById(id: string): Promise<RepairDetailEnriched | undefined> {
  const result = await repoFindRepairById(id)
  if (!result) return undefined

  // Fetch related data
  const [bicycle] = await db.select().from(bicycles).where(eq(bicycles.id, result.bicycleId))
  let customer: typeof customers.$inferSelect | undefined
  if (bicycle?.customerId) {
    const [cust] = await db.select().from(customers).where(eq(customers.id, bicycle.customerId))
    customer = cust ?? undefined
  }

  const lineItems = await repoFindLineItemsByRepairId(id)
  const workLogsList = await repoFindWorkLogsByRepairId(id)

  return {
    repair: {
      id: result.id,
      bicycleId: result.bicycleId,
      assignedTo: result.assignedTo,
      status: result.status as RepairStatus,
      customerNotes: result.customerNotes,
      internalNotes: result.internalNotes,
      holdReason: result.holdReason as HoldReason | null,
      holdReasonNote: result.holdReasonNote,
      plannedDate: result.plannedDate ?? null,
      pickupDate: result.pickupDate ?? null,
      completedAt: result.completedAt ?? null,
      createdAt: result.createdAt,
    },
    customer: customer ? {
      id: customer.id,
      firstName: customer.firstName,
      lastName: customer.lastName,
      companyName: customer.companyName,
      phone: customer.phone,
      email: customer.email,
    } : undefined,
    bicycle: {
      id: bicycle!.id,
      brand: bicycle!.brand,
      model: bicycle!.model,
      color: bicycle!.color,
      year: bicycle!.year,
    },
    lineItems,
    workLogs: workLogsList.map((wl) => ({
      id: wl.id,
      repairId: wl.repairId,
      userId: wl.userId,
      startedAt: Number(wl.startedAt),
      endedAt: wl.endedAt != null ? Number(wl.endedAt) : null,
      durationMs: wl.endedAt != null && wl.startedAt != null ? Number(wl.endedAt) - Number(wl.startedAt) : undefined,
    })),
  }
}

